package net.civeira.phylax.feature.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class IntrospectionAllowedVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property introspection allowed of oauth client ")
  void test_introspection_allowed_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> IntrospectionAllowedVO.tryFrom(null));
    Assertions.assertEquals(true, IntrospectionAllowedVO.from(true).isIntrospectionAllowed());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> IntrospectionAllowedVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", IntrospectionAllowedVO.from(true).toString());
  }
}
